EditorApplication.delayCall+=()=>{try{
var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(Racer.Editor.BackyardForwardAuthoring.ScenePath);var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();race.road.Initialize();var c=race.GetComponent<Racer.BackyardForwardCourse>();
float Delta(Vector3 p){float v=0;for(int j=1;j<3;j++){var q=p-c.flightStarts[j];float along=Vector3.Dot(q,c.flightDirections[j]);float side=Math.Abs(Vector3.Dot(q,Vector3.Cross(Vector3.up,c.flightDirections[j])));if(along>=-42&&along<=.5f&&side<4.65f)v+=(j==1?2.4f:2.2f)*Mathf.Pow(Mathf.Clamp01((along+42)/42),2)*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2.65f,4.65f,side)));}return v;}
foreach(var mf in GameObject.Find("Memory loop - north is +Z").GetComponentsInChildren<MeshFilter>()){if(!AssetDatabase.GetAssetPath(mf.sharedMesh).StartsWith(Racer.Editor.BackyardForwardAuthoring.Folder+"/Ground_"))continue;var m=mf.sharedMesh;var v=m.vertices;bool edit=false;for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);float dy=Delta(p);if(dy<.00001f)continue;p.y+=dy;v[i]=mf.transform.InverseTransformPoint(p);edit=true;}if(edit){m.vertices=v;m.RecalculateNormals();m.RecalculateBounds();EditorUtility.SetDirty(m);mf.GetComponent<MeshCollider>().sharedMesh=null;mf.GetComponent<MeshCollider>().sharedMesh=m;}}
var pts=race.road.points;for(int i=0;i<pts.Length;i++){float dy=Delta(pts[i]);if(dy>0)pts[i].y+=dy;else for(int j=1;j<3;j++){float t=Vector3.Dot(pts[i]-c.flightStarts[j],c.flightDirections[j]);float length=j==1?46:35;if(t>0&&t<length&&Math.Abs(Vector3.Dot(pts[i]-c.flightStarts[j],Vector3.Cross(Vector3.up,c.flightDirections[j])))<1)pts[i].y+=(j==1?2.4f:2.2f)*(1-t/length);}}
var go=race.road.gameObject;UnityEngine.Object.DestroyImmediate(race.road);race.road=go.AddComponent<Racer.RaceRoad>();race.road.points=pts;race.road.forestTrail=true;race.road.Initialize();for(int j=0;j<3;j++){if(j>0)c.flightStarts[j].y+=j==1?2.4f:2.2f;c.launchStations[j]=race.road.Project(c.flightStarts[j],out _);var p=c.flightStarts[j]+c.flightDirections[j]*(j==0?51.15f:j==1?46:35);p.y=Physics.RaycastAll(new Vector3(p.x,250,p.z),Vector3.down,500,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>h.distance).First().point.y;c.landingStations[j]=race.road.Project(p,out _);}
var f=UnityEngine.Object.FindAnyObjectByType<Racer.ForestLayout>();for(int j=0;j<3;j++){f.jumpStarts[j]=c.launchStations[j];f.jumpEnds[j]=c.landingStations[j];}Physics.SyncTransforms();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Racer.Editor.BackyardForwardAuthoring.Export();System.IO.File.WriteAllText("Docs/BackyardForward/gully-lips.txt","Two gully takeoffs retain 42m smooth entry; final rises 6m and 4.5m over original terrain for full ravine clearance, with original far banks preserved.");
}catch(Exception e){System.IO.File.WriteAllText("Docs/BackyardForward/gully-lips-error.txt",e.ToString());}};return "Scheduled two gully lip adjustments for full bank-to-bank clearance";
